			function onBodyLoad(e){
			    var voIntiValue = app.getHostProperty("initValue");
			    
			    util.Submit.send(app, "subOnload", function(pbSuccess){
			        
			        var dsBoardList = app.lookup("dsBoardList");        
			                
			        if(voIntiValue["type"] == "READ"){
			            if(voIntiValue["index"]){
			                var index = voIntiValue["index"];
			                util.DataMap.setValue(app, "dmDetail", "INDEX", index);
			                util.Submit.send(app, "subDetail", function(pbSuccess){
			                    if(pbSuccess){
			                        //첨부 파일 조회
			                        app.lookup("cmnMultifileupload").getFiles();
			                        
			                        dsBoardList.setRowState(0, cpr.data.tabledata.RowState.UNCHANGED);//상태값변경x                            
			                        util.Control.setVisible(app, false, ["btnSave"]);
			                        app.lookup("grpBoardDtl").redraw();                                 
			                    }
			                });
			            }         
			        }
			//------------------------------------------------------------------등록click 
			         else if(voIntiValue["type"] == "CREATE"){
			            
			            util.Control.setVisible(app, false, ["btnDelete", "btnRevise", "btnRestore"]);
			            util.Control.setVisible(app, true, ["btnSave", "btnList"]);
			            util.Control.setReadOnly(app, false, ["cmbMnlaGroupNm","cmbMnlaSeCdNm","grpBoardDtl"]);
			            dsBoardList.addRow();
			            
			//            var vcGrpBoradDtl = app.lookup("grpBoardDtl");
			//            var vcEditer = app.lookup("cmnHtmlEditor");
			            var vcGrpCont = app.lookup("grpCont");
			            // html스니펫, 에디터 전환 
			            vcGrpCont.getLayout().setRowVisible(0, false);
			            vcGrpCont.getLayout().setRowVisible(1, true);
			           
			            
			        }
			    });
			}

			/*
			 * "저장" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick(e){
			    var btnSave = e.control;
			    
			// 입력 프리폼 유효성 체크
			    if (!util.validate(app, "grpBoardDtl")) return false;

			    var vcHtmlEdit = app.lookup("cmnHtmlEditor");//에디터
			    var vcfld = app.lookup("cmnMultifileupload");//첨부파일
			    var vsContent = vcHtmlEdit.getValue();//에디터 값
			    var vsBeforeCn = util.DataSet.getValue(app, "dsBoardList", 0, "MNLA_CN");
			    
			    var vbIsModified = false;
			    
			    if(util.FreeForm.isModified(app, "grpBoardDtl")){
			        vbIsModified = true;
			    } else if(vcfld.isFileModified()){
			        vbIsModified = true;
			    } else if(vsContent != vsBeforeCn){
			        vbIsModified = true;
			    }
			    
			    if(vbIsModified){ // 변경사항이 있을때 저장 작업    
			        util.DataSet.setValue(app, "dsBoardList", 0, "MNLA_CN", vsContent);
			        
			        vcfld.send(doSave);
			        
			    } else { // 변경사항이 없을때 알림    
			        util.Msg.alert(app, "INF-M006");
			    }
			}


			/**
			 * 게시글 상세 CRUD 권한 처리 
			 * @param {"CREATE" | "READ" | "UPDATE"} psType CRUD Type
			 */
			function boardDtlCrud(psType) {
			    
			    var vcGrpBoradDtl = app.lookup("grpBoardDtl");
			    var vcGrpCont = app.lookup("grpCont");
			    var vcEditer = app.lookup("cmnHtmlEditor");
			    
			    if (psType == "READ") {    
			        util.Control.setReadOnly(app, true, "grpBoardDtl");        
			//        // editor 숨김처리 및 html 스니펫 출력
			        vcGrpCont.getLayout().setRowVisible(0, true);
			        vcGrpCont.getLayout().setRowVisible(1, false);       
			        util.Control.setVisible(app, false, ["btnSave", "btnRestore"]);
			        util.Control.setVisible(app, true, ["btnDelete", "btnRevise"]);
			              
			    } else {
			        
			        util.Control.setReadOnly(app, false, "grpBoardDtl");
			        
			        // html스니펫, 에디터 전환 
			        vcGrpCont.getLayout().setRowVisible(0, false);
			        vcGrpCont.getLayout().setRowVisible(1, true);
			        
			        if (psType == "UPDATE") {
			            util.Control.setVisible(app, "false", ["btnDelete","btnRevise"]);
			            var vcEditer = app.lookup("cmnHtmlEditor");
			            var mnlaCn = util.DataSet.getValue(app, "dsBoardList", 0, "MNLA_CN");
			            
			            cpr.core.DeferredUpdateManager.INSTANCE.asyncExec(function() {
			                vcEditer.setValue(mnlaCn);
			            });
			            
			        } 

			        util.Control.setVisible(app, true, ["btnSave", "btnRestore"]);
			        util.Control.setVisible(app, false, ["btnDelete", "btnRevise"]);
			    
			    }
			}

			/**
			 * 데이터 저장 서브미션 호출
			 */
			function doSave(psStatus) {
			    
			    // 저장 서브미션 호출
			    util.Submit.send(app, "subSave", function(pbSuccess) {
			        if (pbSuccess) {
			                       
			            if(psStatus=="delete"){
			                
			                app.close();
			            }else{
			                //신규저장시 디테일로 brdseq값 전달 
			                var vnBbsENo = app.lookup("subSave").getMetadata("MNLA_NO");
			                console.log("vnBbsENo::"+vnBbsENo);
			                
			                if(ValueUtil.isNull(vnBbsENo)){
			                    vnBbsENo = util.DataSet.getValue(app, "dsBoardList", 0, "MNLA_NO");
			                }
			                
			                console.log("NO:"+vnBbsENo);
			                util.DataMap.setValue(app, "dmDetail", "INDEX", vnBbsENo);
			                util.Submit.send(app, "subDetail", function(pbSuccess){
			                    if(pbSuccess){
			                        app.lookup("grpBoardDtl").redraw();
			                        boardDtlCrud("READ");                
			                    }
			                });              
			            }
			//            doList("save", vnBbsENo);
			        }
			    });
			}

